body.usercss:

div.group_collapse_icon.angle-down-thin {
	background-image:url('<%=CONTEXT_NAME%>/resource/design/imgs/menu/angle-down-thin.png');
	background-repeat: no-repeat;
	background-position-y: center;
	background-size: 90%;
}

userscript.function:

	var accordionBackgroundColor = Sepoa.config.get('css.accordion.background.color');
    if (accordionBackgroundColor) $('.MENU').css('background-color', accordionBackgroundColor);

	$sObject._vp.parents('body')[0].addEventListener('click', function(e){
		if(e.srcElement.classList.contains('frame')){
			window.top.Sepoa.callEvent('onMenuBlankClick', []);
		}
	})
    setTimeout(doQueryMenu,200);
    $(window).on({
        resize:function(){
            menuAreaResize();
        }
    });
    extendO2W($sObject);
    if(Sepoa.request.isFixed == 'true' && Sepoa.request.screen){
        callFunction(Sepoa.request.screen, 'setMenuWidth', [$sObject._vp[0].offsetWidth])
    }


        	menuObj.onGroupClick=function(obj){
        		$(".sepoa_menu_screen").slideUp();
				$(".sepoa_menu_group_li").removeClass("group_active")
				if(!$(obj).next().is(":visible")){
					$(obj).parent().addClass("group_active")
					$(obj).next().slideDown();
				}
        	}

        	SepoaLeftMenu.innerHTML = "";
        	SepoaLeftMenu.classList.add("sepoa_menu");

        	var ul = SepoaLeftMenu.appendChild($('<ul class="sepoa_menu_group" id="sepoa_menu_group"></ul>')[0]);

            for(var i in menuTree){
                var groupData = menuTree[i];
                var childNodes = groupData.childs;

                if(groupData.HIDDEN_FLAG == "Y" || groupData.MENU_FILTERED_YN == "N"){
                    continue;
                }
                if(childNodes.length <= 0){
                    continue;
                }

				var li = ul.appendChild(document.createElement('li'));
        		li.id = "sepoa_menu_group_"+groupData.MENU_ID
        		li.classList.add("sepoa_menu_group_li")

				var menuName = Sepoa.cache.text.get('MENU_' + groupData.MENU_PROFILE_CODE + '.' + groupData.MENU_ID);
				if(menuName.indexOf('Has not found text') == 0) {
					menuName = groupData.MENU_NAME;
				}

        		var h3 = li.appendChild(document.createElement('h3'));
                if(groupData.MENU_IMG && groupData.MENU_IMG.indexOf("xi-") == 0){
                   h3.innerHTML = '<div class="sepoa_menu_group_icon '+groupData.MENU_IMG+'"></div>'+ menuName +'<div class="group_collapse_icon angle-down-thin"></div>';
                }else{
        	       h3.innerHTML = '<div style="'+(groupData.MENU_IMG?('background-image:url(\''+window.CONTEXT_NAME+'/resource/design/imgs/menu/'+groupData.MENU_IMG+'\');'):(''))+'"></div>'+ menuName +'<div class="group_collapse_icon angle-down-thin"></div>';
                }
        		h3.onclick = function(){
	        		menuObj.onGroupClick(this);
    	    	}

        		var subUl = li.appendChild(document.createElement('ul'));
        		subUl.classList.add("sepoa_menu_screen");
                const isManageConfirmer = Sepoa.info.CTRL_CODE.split(',').indexOf('MANAGE_CONFIRM') > -1;
                const isSealAdmin = Sepoa.info.MENU_PROFILE_CODE == Sepoa.config.get('sepoa.legal.porfile.code');

                for(var j in childNodes){
                    var detailData = childNodes[j];
                    var screenID = detailData.SCREEN_ID || "";
                    var menuID = detailData.MENU_ID || "";
                    var url = detailData.URL || "";
                    var menuImage = detailData.MENU_IMG || "";

                    if (isManageConfirmer && ['SLM_122','SLM_152'].indexOf(screenID) > -1) continue;	// 인감관리승인자는 등록, 반납 메뉴 없애기 (승인만 가능)
                    if (screenID == 'SLM_160' && !isManageConfirmer) continue; // 인감관리승인자가 아니면 처리대상 없애기

                    if(childNodes[j].HIDDEN_FLAG == "Y" || childNodes[j].MENU_FILTERED_YN == "N"){
                        continue;
                    }

                    var detailMenuName = Sepoa.cache.text.get('MENU_' + detailData.MENU_PROFILE_CODE + '.' + detailData.MENU_ID);
					if(detailMenuName.indexOf('Has not found text') == 0) {
						detailMenuName = detailData.MENU_NAME;
					}

                    var li = subUl.appendChild(document.createElement('li'))
					li.id = "sepoa_menu_screen_"+detailData.MENU_ID
					li.classList.add("sepoa_menu_screen_li");
					li.style.display=(detailData.HIDDEN_FLAG == 'Y')?"none":""
					li.innerHTML = detailMenuName;
					li.screenId = detailData.SCREEN_ID;
					li.url = detailData.URL;
					li.onclick = function(){
						var _id = this.screenId
						var _url = this.url
						var _param = this.param
						var _menuName = this.innerHTML
						callFunction('MAINFRAME','openContainerUrl', [_id, _url, _param, _menuName]);
					}
                }
            }

            var accordionTextColor = Sepoa.config.get('css.accordion.text.color');
            if (accordionTextColor) {
            	$('.sepoa_menu .sepoa_menu_group_li > h3').css('color', accordionTextColor);
            	$('.sepoa_menu .sepoa_menu_screen li').css('color', accordionTextColor);
            }
            var accordionBorderColor = Sepoa.config.get('css.accordion.border.color');
            if (accordionBorderColor) $('.sepoa_menu .sepoa_menu_group_li').css('border-bottom-color', accordionBorderColor);
